"""Fetch the third-party board assets into book/assets.

Run by hand (`make vendor`), never by the build: the book renders from what is
already on disk, and these files are committed. Every pin below is exact, so a
later run either writes the same bytes or says what changed.

Each piece set becomes one stylesheet of data URIs, the way the viewer ships
its own, so a board that changes set fetches no image and the page that never
changes it fetches nothing.
"""

import base64
import json
import os
import sys
import urllib.request

ASSETS = os.path.join(os.path.dirname(__file__), "..", "..", "book", "assets")

# name in book/assets -> where it came from
FILES = {
    # The board. Legality, SAN and the end of a game come from chess.js; the
    # squares and the dragging from chessground. Both are ES modules.
    "chessground.min.js":
        "https://unpkg.com/chessground@9.2.1/dist/chessground.min.js",
    "chess.js":
        "https://unpkg.com/chess.js@1.4.0/dist/esm/chess.js",
    # Stockfish 19, lite and single-threaded: the only build that needs no
    # SharedArrayBuffer, and so the only one GitHub Pages can serve, since it
    # cannot send the COOP and COEP headers the threaded builds require.
    "stockfish-19-lite-single.js":
        "https://github.com/nmrugg/stockfish.js/releases/download/v19.0.1/"
        "stockfish-19-lite-single.js",
    "stockfish-19-lite-single.wasm":
        "https://github.com/nmrugg/stockfish.js/releases/download/v19.0.1/"
        "stockfish-19-lite-single.wasm",
}

# The piece sets a reader can choose between. lichess has forty-three; most are
# CC BY-NC-SA, which a published book cannot use, and of the rest these are the
# ones worth offering. cburnett is the default and already inlined in the
# viewer's own stylesheet, so it is listed but not fetched.
PIECE_REF = "5b44d719ec5913dd62aa965f4b8d21e60a00c2c1"
PIECE_URL = ("https://raw.githubusercontent.com/lichess-org/lila/%s"
             "/public/piece/%s/%s.svg")
SETS = [
    ("cburnett",   "Colin M.L. Burnett",          "GPLv2+"),
    ("merida",     "Armando Hernandez Marroquin", "GPLv2+"),
    ("mpchess",    "Maxime Chupin",               "GPLv3+"),
    ("celtic",     "Maurizio Monge",              "MIT"),
    ("fantasy",    "Maurizio Monge",              "MIT"),
    ("spatial",    "Maurizio Monge",              "MIT"),
    ("chessnut",   "Alexis Luengas",              "Apache 2.0"),
    ("rhosgfx",    "RhosGFX",                     "CC0 1.0"),
    ("totoy",      "Kosal Sen",                   "CC BY 4.0"),
    ("kiwen-suwi", "neverRare",                   "CC BY 4.0"),
    ("papercut",   "Nikolay Anzarov",             "CC BY 4.0"),
]
ROLES = {"P": "pawn", "N": "knight", "B": "bishop",
         "R": "rook", "Q": "queen", "K": "king"}


def piece_css(name, author, licence):
    """One rule per piece, each sprite inlined, all under a single class."""
    rules = []
    for colour in ("w", "b"):
        for letter, role in ROLES.items():
            svg = get(PIECE_URL % (PIECE_REF, name, colour + letter))
            # A couple of these carry two style attributes on the root tag,
            # which is not well-formed, and a browser then refuses the image.
            head = svg[:svg.index(b">") + 1]
            if head.count(b'style="') > 1:
                svg = svg.replace(b' style="color-scheme:light only"', b"", 1)
            rules.append(
                '.pieces-%s .cg-wrap piece.%s.%s{background-image:'
                'url("data:image/svg+xml;base64,%s")}'
                % (name, role, "white" if colour == "w" else "black",
                   base64.b64encode(svg).decode()))
    head = ("/* The %s piece set, by %s, %s.\n"
            "   lichess-org/lila@%s public/piece/%s\n"
            "   Generated by scripts/build/vendor.py. */\n"
            % (name, author, licence, PIECE_REF, name))
    return (head + "\n".join(rules) + "\n").encode()


def pieces():
    out = os.path.join(ASSETS, "pieces")
    os.makedirs(out, exist_ok=True)
    for name, author, licence in SETS:
        if name == "cburnett":
            continue        # the viewer already carries it
        write(os.path.join("pieces", name + ".css"),
              piece_css(name, author, licence))
    # The list the board reads, written here so the credits and the files can
    # never disagree.
    listing = [{"id": n, "by": a, "licence": l} for n, a, l in SETS]
    write(os.path.join("pieces", "sets.js"),
          ("// Generated by scripts/build/vendor.py.\n"
           "export const SETS = %s;\n"
           % json.dumps(listing, indent=2)).encode())


def get(url):
    print("  %s" % url)
    with urllib.request.urlopen(url) as fh:
        return fh.read()


def write(name, data):
    path = os.path.join(ASSETS, name)
    old = open(path, "rb").read() if os.path.exists(path) else None
    with open(path, "wb") as fh:
        fh.write(data)
    print("%-32s %7.1f KB %s"
          % (name, len(data) / 1024,
             "unchanged" if old == data else "new" if old is None else "CHANGED"))


def main():
    if not os.path.isdir(ASSETS):
        sys.exit("no %s" % ASSETS)
    for name, url in FILES.items():
        data = get(url)
        # The map is not shipped, so the comment pointing at it only makes the
        # browser ask for a file that is not there.
        if name.endswith(".js"):
            data = b"\n".join(l for l in data.split(b"\n")
                              if not l.startswith(b"//# sourceMappingURL="))
        write(name, data)
    pieces()


if __name__ == "__main__":
    main()
